        # bridge usage only when day changes between adjacent positions
        for prev, cur in zip(rows_sorted, rows_sorted[1:]):
            if days[cur['day_id']]['day_index'] > days[prev['day_id']]['day_index']:
                region = pairs[prev['pair_id']]['region']
